package main

import (
	"bufio"
	"fmt"
	"os"
)

const MaxN = 2e3 + 23

const MOD = 998244353

var pless, pgreater int
var CP [][]int
var STRONG [MaxN]int
var ans [MaxN]int

func bpow(a, b int) int {
	if b == 0 {
		return 1
	}
	res := bpow(a, b>>1)
	res = (res * res) % MOD
	if b&1 != 0 {
		res = (res * a) % MOD
	}
	return res
}

func calcCP(n, s int) {
	if s == 0 {
		CP[n][s] = 1
	} else {
		CP[n][s] = (CP[n-1][s-1]*bpow(pgreater, n-s))%MOD + (CP[n-1][s]*bpow(pless, s))%MOD
		if CP[n][s] >= MOD {
			CP[n][s] -= MOD
		}
	}
}

func calcStrong(n int) {
	STRONG[n] = 1
	if n > 1 {
		for i := 1; i < n; i++ {
			STRONG[n] -= (STRONG[i] * CP[n][i]) % MOD
			if STRONG[n] < 0 {
				STRONG[n] += MOD
			}
		}
	}
}

func calcAns(n int) {
	if n < 2 {
		ans[n] = 0
	} else {
		for i := 1; i <= n; i++ {
			t := 0
			if i < n {
				t = ans[i]
			}
			ans[n] += STRONG[i] * CP[n][i] % MOD * (i*(n-i) + (i*(i-1))/2 + t + ans[n-i]) % MOD
			if ans[n] >= MOD {
				ans[n] -= MOD
			}
		}
		coef := 1 - (STRONG[n]*CP[n][n])%MOD

		if coef < 0 {
			coef += MOD
		}

		ans[n] = (ans[n] * bpow(coef, MOD-2)) % MOD
	}
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	var n, a, b int
	fmt.Fscan(reader, &n, &a, &b)

	CP = make([][]int, MaxN)
	for i := range CP {
		CP[i] = make([]int, MaxN)
	}

	pless = (a * bpow(b, MOD-2)) % MOD
	pgreater = ((b - a) * bpow(b, MOD-2)) % MOD

	for i := 0; i <= n; i++ {
		for j := 0; j <= i; j++ {
			calcCP(i, j)
		}
	}

	for i := 0; i <= n; i++ {
		calcStrong(i)
	}

	for i := 0; i <= n; i++ {
		calcAns(i)
	}

	fmt.Fprintf(writer, "%d\n", ans[n])
}
